"""Apply explicit local draft decisions; does not publish or touch account data."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'assets/legal/policies.json'
d=json.loads(p.read_text(encoding='utf-8'))
d['approval_required']=[x for x in d['approval_required'] if x!='retention_legal_review']+['final_legal_retention_schedule']
for row in d['policies']:
    if row['key']=='conduct':
        row['ar']=row['ar'].replace('عند حذف الحساب، تقترح السياسة التشغيلية فصل هوية المرسل من النص المشترك مع إبقاء النص للطرف الآخر، وحذف صور المحادثة التي أرسلها الحساب، عدا احتفاظ قانوني موثق ومقيد.', 'عند اكتمال حذف الحساب تُحذف نصوص رسائله وصوره ومرفقاته من المحادثات الخاصة والجماعية، ويظهر «رسالة محذوفة» دون هوية المرسل. تبقى رسائل الآخرين دون تغيير. الاستثناء القانوني الموثق يحفظ منفصلًا ومقيدًا ولا يبقى ظاهرًا في المحادثة.')
        row['en']=row['en'].replace('The proposed deletion policy separates the deleted sender\'s identity from shared text while retaining text for the recipient, and deletes chat images uploaded by the deleted account except under a documented restricted legal hold.', 'On completed account deletion, its sent text, images and attachments in private and group chats are removed and shown as “Deleted message” without sender identity. Other parties’ messages remain unchanged. Documented lawful exceptions are archived separately under restricted access and are not visible in chat.')
    if row['key']=='deletion':
        row['ar']=row['ar'].replace('يبقى نص الرسائل المشتركة للطرف الآخر مع إزالة هوية الحساب وفصل ارتباطه به. تُحذف صور المحادثة المرسلة منه وتظهر كمرفق غير متاح، إلا عند التزام قانوني موثق. لا نعد بإزالة هوية مكتوبة داخل محتوى الرسائل دون مراجعة إضافية، ولا نسترجع نسخًا نُزلت خارج المنصة.', 'تُحذف نصوص الرسائل والصور والمرفقات التي أرسلها صاحب الحساب من المحادثات الخاصة والجماعية عند اكتمال الحذف، ويظهر «رسالة محذوفة» دون اسم أو صورة أو معلومات تكشف هوية الحساب. تبقى رسائل الآخرين دون تغيير. أي نسخة لازمة قانونيًا تحفظ منفصلة ومقيدة ولا تبقى ظاهرة في المحادثة. لا نسترجع نسخًا نُزلت خارج المنصة.')
        row['en']=row['en'].replace('Shared message text remains for recipients with sender identity removed and detached. Chat images sent by the deleted account are removed and shown as unavailable attachments unless subject to documented lawful retention. Personal information inside message text requires separate review; no promise is made to recall copies downloaded outside Arena.', 'On completion, text, images and attachments sent by the account are deleted from private and group chats and replaced with “Deleted message” without sender name, avatar or identifying details. Other parties’ messages are unchanged. Any legally necessary copy is archived separately with restricted access and hidden from chat. Copies downloaded outside Arena cannot be recalled.')
        row['ar']+='\n\nاعتماد لاحق: مدد 5 و10 سنوات ليست احتفاظًا شاملًا ببيانات الحساب أو الحجوزات. يُوثق الغرض أو السند القانوني لكل سجل وحقل والاستثناءات وصلاحيات الوصول. تُحذف أو تُجهّل البيانات فور انتهاء الغرض ما لم يوجد التزام قانوني أو نزاع قائم. الثلاثون يومًا سقف تنفيذ عند انطباق الطلب وليست انتظارًا تلقائيًا. يبقى الجدول القانوني النهائي معلقًا للمراجعة.'
        row['en']+='\n\nSubsequent approval: five- and ten-year proposals are not blanket retention for account or booking data. Each retained record and field needs a documented purpose or legal basis, exceptions and restricted access. Data is erased or anonymized when its purpose ends unless a legal obligation or live dispute applies. Thirty days is the execution ceiling where applicable, not an automatic waiting period. The final legal retention schedule remains pending review.'
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
